| Then {AB: 1, CD: 1, BP: -1, MP: 1, AX: -1, BX: 1, AW1: 1, NW1: 1/2, CE: -1, NQ: -1, AQ: -1, QW1: 1/2, BO2: -1/2, CO2: -1/2, BM: 1/2, BW2: -1/2, MW2: -1/2, CM: -1/2, MO2: 1} + -1/2 x {BO2: -1, CO2: -1, MO2: 2}
